using System.Windows; using System.Windows.Controls; using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; using Microsoft.EntityFrameworkCore; namespace AutoPecasERP.Desktop.Views; public partial class ProdutosWindow:Window{public ProdutosWindow(){InitializeComponent();Carregar();}async void Carregar(string q=""){using var db=new ErpDbContext();GridDados.ItemsSource=await db.Produtos.Where(x=>q==""||x.Descricao.Contains(q)||x.CodigoInterno.Contains(q)||(x.CodigoFabricante??"").Contains(q)||(x.CodigoBarras??"").Contains(q)).OrderBy(x=>x.Descricao).ToListAsync();}void Busca_TextChanged(object s,TextChangedEventArgs e)=>Carregar(Busca.Text.Trim());void Novo_Click(object s,RoutedEventArgs e){var w=new ProdutoEditWindow(){Owner=this};if(w.ShowDialog()==true)Carregar();}void Movimentar_Click(object s,RoutedEventArgs e){if(GridDados.SelectedItem is not Produto p){MessageBox.Show("Selecione um produto.");return;}var w=new EstoqueWindow(p.Id){Owner=this};w.ShowDialog();Carregar(Busca.Text.Trim());}}